package com.soulsync.config;
import com.soulsync.domain.Enums.UserStatus; import org.springframework.beans.factory.annotation.Value; import com.soulsync.repository.UserRepository; import com.soulsync.security.JwtService; import lombok.RequiredArgsConstructor; import org.springframework.context.annotation.Configuration; import org.springframework.messaging.*; import org.springframework.messaging.simp.config.*; import org.springframework.messaging.support.ChannelInterceptor; import org.springframework.messaging.support.MessageHeaderAccessor; import org.springframework.messaging.simp.stomp.StompHeaderAccessor; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.web.socket.config.annotation.*; import java.util.*;
@Configuration @EnableWebSocketMessageBroker @RequiredArgsConstructor
public class WebSocketConfig implements WebSocketMessageBrokerConfigurer { private final JwtService jwt; private final UserRepository users; @Value("${soulsync.frontend-url}") String frontend;
 @Override public void configureMessageBroker(MessageBrokerRegistry r){r.enableSimpleBroker("/queue");r.setApplicationDestinationPrefixes("/app");r.setUserDestinationPrefix("/user");}
 @Override public void registerStompEndpoints(StompEndpointRegistry r){r.addEndpoint("/ws").setAllowedOrigins(frontend);}
 @Override public void configureClientInboundChannel(ChannelRegistration reg){reg.interceptors(new ChannelInterceptor(){@Override public Message<?> preSend(Message<?> msg,MessageChannel ch){var a=MessageHeaderAccessor.getAccessor(msg,StompHeaderAccessor.class);if(a!=null&&a.getCommand()==org.springframework.messaging.simp.stomp.StompCommand.CONNECT){String h=a.getFirstNativeHeader("Authorization");if(h==null||!h.startsWith("Bearer "))throw new IllegalArgumentException("Missing WebSocket bearer token");var c=jwt.parse(h.substring(7));var id=UUID.fromString(c.getSubject());var u=users.findById(id).filter(x->x.getStatus()==UserStatus.ACTIVE).orElseThrow();a.setUser(new UsernamePasswordAuthenticationToken(id.toString(),null,List.of(new SimpleGrantedAuthority("ROLE_"+u.getRole().name()))));}return msg;}});}
}
